import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Input, Select, Row, Button } from 'antd'

import { AddUserStyle } from './index.style'
import providerAction from '../../../redux/provider/actions'
import { map, get } from 'lodash'

const { getGroupList, addProviderUser, updateProviderUser } = providerAction

const FormItem = Form.Item
const { Option } = Select

class AddUser extends Component {
  state = {
    open: false,
    editUserData: {}
  }

  componentDidMount () {
    this.props.getGroupList()
  }

  componentWillReceiveProps (nextProps) {
    const { editUserData, visible } = nextProps
    const { open } = this.state

    if (visible !== open) {
      const { email, name, is_internal_user: isInternalUser, groups } = editUserData
      let userGroups = groups && map(groups, 'name')
      this.setState({ editUserData, open: visible })
      this.props.form.setFieldsValue({
        name,
        email,
        is_internal_user: isInternalUser,
        groups: userGroups
      })
    }
  }

  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { providerCode, editUserData } = this.props
        if (Object.keys(editUserData).length > 0) {
          this.props.updateProviderUser({
            body: {
              ...values,
              user_id: get(editUserData, 'id')
            },
            query: {
              code: providerCode
            }
          })
        } else {
          this.props.addProviderUser({
            body: values,
            query: {
              code: providerCode
            }
          })
        }
      }
    })
  }

  render () {
    const { form, providerGroupList = [], editUserData = {} } = this.props
    const { getFieldDecorator } = form
    const { email, name, is_internal_user: isInternalUser, groups } = editUserData
    let userGroups = groups && map(groups, 'name')

    return (
      <AddUserStyle>
        <Form onSubmit={this.handleSubmit}>
          <FormItem label='Name'>
            {getFieldDecorator('name', {
              rules: [
                { required: true, message: `Name can not be empty` }
              ],
              initialValue: name
            })(
              <Input
                placeholder='Name'
              />
            )}
          </FormItem>
          <FormItem label='Email'>
            {getFieldDecorator('email', {
              rules: [
                { required: true, message: `Email can not be empty` }
              ],
              initialValue: email
            })(
              <Input type='email' placeholder='Email' disabled={!!email} />
            )}
          </FormItem>
          <FormItem label='Group'>
            {getFieldDecorator('groups', {
              rules: [
                { required: true, message: `Groups can not be empty` }
              ],
              initialValue: userGroups
            })(
              <Select
                mode='multiple'
                placeholder='Select Groups'
              >
                {
                  providerGroupList.map(name => <Option key={name} value={name}>{name}</Option>)
                }
              </Select>
            )}
          </FormItem>
          <FormItem label='Is Internal'>
            {getFieldDecorator('is_internal_user', {
              rules: [
                { required: true, message: `Is internal can not be empty` }
              ],
              initialValue: isInternalUser
            })(
              <Select
                placeholder='Is Internal'
                disabled={!!isInternalUser}
              >
                <Option value>Yes</Option>
                <Option value={false}>No</Option>
              </Select>
            )}
          </FormItem>
          <Row type='flex' justify='end'>
            <FormItem>
              <Button
                type='primary'
                htmlType='submit'
              >
                Submit
              </Button>
            </FormItem>
          </Row>
        </Form>
      </AddUserStyle>
    )
  }
}

const AddUserWrapper = Form.create()(AddUser)

export default connect(state => ({
  providerGroupList: state.Provider.providerGroupList
}), {
  getGroupList,
  addProviderUser,
  updateProviderUser
})(AddUserWrapper)
