import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Select, Input, Button, Row, Spin } from 'antd'
import { get } from 'lodash'

import { AddConfigStyle } from './index.style'
import providerAction from '../../../redux/provider/actions'

const { addProviderConfig, updateProviderConfig } = providerAction

const FormItem = Form.Item
const { Option } = Select

class AddConfig extends Component {
  handleSubmit = e => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { providerCode, providerConfig } = this.props
        const update = providerConfig.length > 0
        let providerConfigData = []

        Object.keys(values).forEach(configName => {
          let config = {}
          config['config_type_name'] = configName
          config['value'] = values[configName]
          providerConfigData.push(config)
        })

        if (update) {
          this.props.updateProviderConfig({
            query: {
              code: providerCode
            },
            body: {
              provider_configs: providerConfigData,
              provider_name: providerCode
            }
          })
        } else {
          this.props.addProviderConfig({
            query: {
              code: providerCode
            },
            body: {
              provider_configs: providerConfigData,
              provider_name: providerCode
            }
          })
        }
      }
    })
  }

  renderInputField = (fieldType) => {
    switch (fieldType) {
      case 'bool':
        return <Select>
          <Option value='1'>Yes</Option>
          <Option value='0'>No</Option>
        </Select>
      default:
        return <Input />
    }
  }

  render () {
    const { defaultConfig = [], providerConfig, form, addProviderConfigLoading, updateProviderConfigLoading } = this.props
    const { getFieldDecorator } = form
    const edit = providerConfig.length > 0

    return (
      <AddConfigStyle>
        <Spin spinning={!!addProviderConfigLoading || !!updateProviderConfigLoading}>
          <Form onSubmit={this.handleSubmit}>
            {
              edit
                ? providerConfig.map(({ config_type: configType, value }) =>
                  (
                    <FormItem label={get(configType, 'description')}>
                      {getFieldDecorator(get(configType, 'name'), {
                        rules: [
                          { required: true, message: `${get(configType, 'name')} can not be empty` }
                        ],
                        initialValue: value
                      })(
                        this.renderInputField(get(configType, 'field_type'))
                      )}
                    </FormItem>
                  )
                )
                : defaultConfig.map(({ name, default_value: defaultValue, description, field_type: fieldType }) =>
                  <FormItem label={description}>
                    {getFieldDecorator(name, {
                      rules: [
                        { required: true, message: `${name} can not be empty` }
                      ],
                      initialValue: defaultValue
                    })(
                      this.renderInputField(fieldType)
                    )}
                  </FormItem>
                )
            }
            <Row type='flex' justify='end'>
              <FormItem>
                <Button
                  type='primary'
                  htmlType='submit'
                >
                  {edit ? 'Update' : 'Add'}
                </Button>
              </FormItem>
            </Row>
          </Form>
        </Spin>
      </AddConfigStyle>
    )
  }
}

const WrappedAddConfig = Form.create()(AddConfig)

export default connect(state => ({
  defaultConfig: state.Provider.defaultConfig,
  providerConfig: state.Provider.providerConfig,

  addProviderConfigLoading: state.Loading.ADD_PROVIDER_CONFIG,
  updateProviderConfigLoading: state.Loading.UPDATE_PROVIDER_CONFIG
}), {
  addProviderConfig,
  updateProviderConfig
})(WrappedAddConfig)
