import React, { Component } from 'react'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Card, Row, Col, Table, Icon, Empty, Button, Modal, notification, Spin } from 'antd'

import { ProviderDetailStyle } from './index.style'
import providerAction from '../../../redux/provider/actions'
import loadingActions from '../../../../redux/loading/actions'
import errorActions from '../../../../redux/error/actions'
import AddConfig from './addConfig'
import AddUser from './addUser'

const { getProviderConfig, getProviderUser, getProviderDetails, updateProviderUserStatus } = providerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class ProviderDetails extends Component {
  state = {
    showAddConfigModal: false,
    showAddUserModal: false,
    providerCode: '',
    editUserData: {}
  }

  componentDidMount () {
    const { location } = this.props.history
    if (get(location, 'pathname')) {
      const code = get(location, 'pathname').split('/').pop()
      this.setState({ providerCode: code })
      this.props.getProviderDetails({
        query: {
          code
        }
      })
    }
    this.props.resetLoadingRedux(['ADD_PROVIDER_CONFIG', 'UPDATE_PROVIDER_CONFIG', 'ADD_PROVIDER_USER', 'UPDATE_PROVIDER_USER', 'GET_PROVIDER_DETAILS'])
    this.props.resetErrorRedux(['ADD_PROVIDER_CONFIG', 'UPDATE_PROVIDER_CONFIG', 'ADD_PROVIDER_USER', 'UPDATE_PROVIDER_USER', 'GET_PROVIDER_DETAILS'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { addProviderConfigLoading, addProviderConfigError, addProviderConfigMessage,
      updateProviderConfigLoading, updateProviderConfigError, updateProviderConfigMessage,
      addProviderUserLoading, addProviderUserError, addProviderUserMessage,
      updateProviderUserLoading, updateProviderUserError, updateProviderUserMessage,
      updateProviderUserStatusLoading, updateProviderUserStatusError, updateProviderUserStatusMessage,
      providerDetailsLoading, providerDetailsError, getProviderDetailsMessage
    } = nextProps

    if (providerDetailsLoading === false && providerDetailsError) {
      notification['error']({ message: getProviderDetailsMessage })
      this.props.history.replace({ pathname: 'list' })
      this.props.resetLoadingRedux(['GET_PROVIDER_DETAILS'])
      this.props.resetErrorRedux(['GET_PROVIDER_DETAILS'])
    }

    if (addProviderConfigLoading === false) {
      notification[addProviderConfigError ? 'error' : 'success']({ message: addProviderConfigMessage })
      if (addProviderConfigError === false) {
        this.setState({ showAddConfigModal: false })
      }
      this.props.resetLoadingRedux(['ADD_PROVIDER_CONFIG'])
      this.props.resetErrorRedux(['ADD_PROVIDER_CONFIG'])
    }

    if (updateProviderConfigLoading === false) {
      notification[updateProviderConfigError ? 'error' : 'success']({ message: updateProviderConfigMessage })
      if (updateProviderConfigError === false) {
        this.setState({ showAddConfigModal: false })
      }
      this.props.resetLoadingRedux(['UPDATE_PROVIDER_CONFIG'])
      this.props.resetErrorRedux(['UPDATE_PROVIDER_CONFIG'])
    }

    if (addProviderUserLoading === false) {
      let message = addProviderUserMessage
      if (typeof (message) === 'object') {
        message = JSON.stringify(message)
      }
      notification[addProviderUserError ? 'error' : 'success']({ message: message })
      if (addProviderUserError === false) {
        this.setState({ showAddUserModal: false })
      }
      this.props.resetLoadingRedux(['ADD_PROVIDER_USER'])
      this.props.resetErrorRedux(['ADD_PROVIDER_USER'])
    }

    if (updateProviderUserLoading === false) {
      let message = updateProviderUserMessage
      if (typeof (message) === 'object') {
        message = JSON.stringify(message)
      }
      notification[updateProviderUserError ? 'error' : 'success']({ message: message })
      if (updateProviderUserError === false) {
        this.setState({ showAddUserModal: false, editUserData: {} })
      }
      this.props.resetLoadingRedux(['UPDATE_PROVIDER_USER'])
      this.props.resetErrorRedux(['UPDATE_PROVIDER_USER'])
    }

    if (updateProviderUserStatusLoading === false) {
      notification[updateProviderUserStatusError ? 'error' : 'success']({ message: updateProviderUserStatusMessage })
      if (updateProviderUserStatusError === false) {
        this.setState({ showAddUserModal: false, editUserData: {} })
      }
      this.props.resetLoadingRedux(['UPDATE_PROVIDER_USER_STATUS'])
      this.props.resetErrorRedux(['UPDATE_PROVIDER_USER_STATUS'])
    }
  }

  handleStatusChange = (data) => {
    const { providerCode } = this.state
    this.props.updateProviderUserStatus({
      query: {
        code: providerCode
      },
      body: {
        activate: !get(data, 'is_active'),
        user_id: get(data, 'id')
      }
    })
  }

  displayConfig = ({ value, config_type: configType }) => {
    const { description } = configType
    let configValue = value;
    if( value === "1" ){
      configValue = "True"
    } else if( value === "0") {
      configValue = "False"
    } 
    return <Col span={8} className='config-column'>
      <Row className='config-header'>{description}</Row>
      {configValue}
    </Col>
  }

  renderKeyValue = (key, value) => {
    return <Row>
      <Col span={8} className='key'>
        {key}
      </Col>
      <Col>
        {value || '-'}
      </Col>
    </Row>
  }

  render () {
    const { providerConfig = [], providerUser = [], providerUserLoading, providerConfigLoading,
      providerDetails = {}, providerDetailsLoading, updateProviderUserStatusLoading
    } = this.props
    const { showAddConfigModal, showAddUserModal, editUserData } = this.state
    const {
      name: providerName,
      code: providerCode,
      contact_name: contactName,
      contact_email: contactEmail,
      contact_phone: contactPhone,
      status
    } = providerDetails

    const userColumns = [{
      title: 'Name',
      key: 'name',
      dataIndex: 'name'
    }, {
      title: 'Email',
      key: 'email',
      dataIndex: 'email'
    }, {
      title: 'Active',
      key: 'active',
      dataIndex: 'is_active',
      render: value => value ? 'True' : 'False'
    }, {
      title: 'Is Internal User',
      key: 'last_login',
      dataIndex: 'is_internal_user',
      render: value => value ? 'True' : 'False'
    }, {
      title: 'Actions',
      key: 'action',
      align: 'center',
      render: value => (<Row type='flex' justify='space-between'>
        <Col>
          <div className='revoke-button' onClick={() => this.handleStatusChange(value)}>
            {get(value, 'is_active') ? 'Revoke' : 'Activate'}
          </div>
        </Col>
        {get(value, 'is_active') &&
          <Col>
            <Icon
              type='edit'
              onClick={() => this.setState({ showAddUserModal: true, editUserData: value })}
            />
          </Col>
        }
      </Row>)
    }]

    return (
      <ProviderDetailStyle>
        <Modal
          visible={showAddConfigModal}
          title='Provider Config'
          footer={null}
          onCancel={() => this.setState({ showAddConfigModal: false })}
        >
          <AddConfig providerCode={providerCode} />
        </Modal>
        <Modal
          visible={showAddUserModal}
          title='Provider User'
          footer={null}
          onCancel={() => this.setState({ showAddUserModal: false, editUserData: {} })}
        >
          <AddUser
            providerCode={providerCode}
            editUserData={editUserData}
            visible={showAddUserModal}
          />
        </Modal>
        <Row>
          <Button
            type='primary'
            icon='arrow-left'
            className='back-button'
            onClick={() => this.props.history.goBack()}
          >
            Back
          </Button>
        </Row>
        <Card>
          <Spin spinning={!!providerDetailsLoading}>
            <Row className='header'>Provider Details</Row>
            {this.renderKeyValue('Provider Name', providerName)}
            {this.renderKeyValue('Provider Code', providerCode)}
            {this.renderKeyValue('Contact Name', contactName)}
            {this.renderKeyValue('Contact Email', contactEmail)}
            {this.renderKeyValue('Contact Phone', contactPhone)}
            {this.renderKeyValue('Status', status)}
          </Spin>
        </Card>
        <Card>
          <Row type='flex' justify='space-between'>
            <Col className='header'>Provider Configs</Col>
            <Col>
              <Button
                type='primary'
                icon='form'
                onClick={() => this.setState({ showAddConfigModal: true })}
              >
                {
                  providerConfig.length > 0
                    ? 'Update Config'
                    : 'Add Config'
                }
              </Button>
            </Col>
          </Row>
          <Spin spinning={!!providerConfigLoading}>
            <Row>
              {
                providerConfig.length > 0
                  ? providerConfig.map(config => this.displayConfig(config))
                  : <Empty description='No Config Found' />
              }
            </Row>
          </Spin>
        </Card>
        <Card>
          <Row type='flex' justify='space-between'>
            <Col className='header'>Provider Users</Col>
            <Col>
              <Button
                type='primary'
                icon='user-add'
                disabled={providerConfig.length === 0}
                onClick={() => this.setState({ showAddUserModal: true })}
              >
                Add User
              </Button>
            </Col>
          </Row>
          <Row>
            <Table
              dataSource={providerUser}
              columns={userColumns}
              loading={!!providerUserLoading || !!updateProviderUserStatusLoading}
              bordered
            />
          </Row>
        </Card>
      </ProviderDetailStyle>
    )
  }
}

export default connect(state => ({
  providerConfigLoading: state.Loading.GET_PROVIDER_CONFIG,
  providerConfig: state.Provider.providerConfig,

  providerUserLoading: state.Loading.GET_PROVIDER_USER,
  providerUser: state.Provider.providerUser,

  addProviderConfigLoading: state.Loading.ADD_PROVIDER_CONFIG,
  addProviderConfigError: state.Error.ADD_PROVIDER_CONFIG,
  addProviderConfigMessage: state.Provider.addProviderConfigMessage,

  updateProviderConfigLoading: state.Loading.UPDATE_PROVIDER_CONFIG,
  updateProviderConfigError: state.Error.UPDATE_PROVIDER_CONFIG,
  updateProviderConfigMessage: state.Provider.updateProviderConfigMessage,

  addProviderUserLoading: state.Loading.ADD_PROVIDER_USER,
  addProviderUserError: state.Error.ADD_PROVIDER_USER,
  addProviderUserMessage: state.Provider.addProviderUserMessage,

  updateProviderUserLoading: state.Loading.UPDATE_PROVIDER_USER,
  updateProviderUserError: state.Error.UPDATE_PROVIDER_USER,
  updateProviderUserMessage: state.Provider.updateProviderUserMessage,

  updateProviderUserStatusLoading: state.Loading.UPDATE_PROVIDER_USER_STATUS,
  updateProviderUserStatusError: state.Error.UPDATE_PROVIDER_USER_STATUS,
  updateProviderUserStatusMessage: state.Provider.updateProviderUserStatusMessage,

  providerDetailsLoading: state.Loading.GET_PROVIDER_DETAILS,
  providerDetailsError: state.Error.GET_PROVIDER_DETAILS,
  providerDetails: state.Provider.providerDetails,
  getProviderDetailsMessage: state.Provider.getProviderDetailsMessage
}), {
  getProviderConfig,
  getProviderUser,
  getProviderDetails,
  updateProviderUserStatus,
  resetLoadingRedux,
  resetErrorRedux
})(ProviderDetails)
